(function () {
  var STORAGE_KEY = "todo-tasks";

  var input = document.getElementById("task");
  var addBtn = document.getElementById("add");
  var clearBtn = document.getElementById("clear");
  var list = document.getElementById("list");
  var total = document.getElementById("total");

  var tasks = load();

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      var parsed = raw ? JSON.parse(raw) : [];
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (t) {
        return typeof t === "string" && t.trim() !== "";
      });
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    } catch (e) {
      // Storage unavailable or full; app keeps working in memory.
    }
  }

  function render() {
    if (list) {
      list.innerHTML = "";
      if (tasks.length === 0) {
        var empty = document.createElement("li");
        empty.className = "empty";
        empty.textContent = "No tasks yet.";
        list.appendChild(empty);
      }
      tasks.forEach(function (text, index) {
        var li = document.createElement("li");
        li.setAttribute("data-testid", "task-item");

        var span = document.createElement("span");
        span.textContent = text;

        var del = document.createElement("button");
        del.type = "button";
        del.className = "small";
        del.textContent = "Delete";
        del.setAttribute("aria-label", "Delete task: " + text);
        del.addEventListener("click", function () {
          tasks.splice(index, 1);
          save();
          render();
          if (input) input.focus();
        });

        li.appendChild(span);
        li.appendChild(del);
        list.appendChild(li);
      });
    }
    if (total) {
      total.textContent = String(tasks.length);
    }
  }

  function addTask() {
    if (!input) return;
    var text = input.value.trim();
    if (text === "") {
      input.value = "";
      input.focus();
      return;
    }
    tasks.push(text);
    input.value = "";
    save();
    render();
    input.focus();
  }

  function clearAll() {
    tasks = [];
    save();
    render();
    if (input) input.focus();
  }

  if (addBtn) addBtn.addEventListener("click", addTask);
  if (clearBtn) clearBtn.addEventListener("click", clearAll);
  if (input) {
    input.addEventListener("keydown", function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        addTask();
      }
    });
  }

  render();
})();

