(function () {
  var KEY = 'todo.items.v1';
  function $(id) { return document.getElementById(id); }

  var form = $('form');
  var input = $('task');
  var list = $('list');
  var total = $('total');
  var clearBtn = $('clear');
  var empty = $('empty');
  var error = $('error');

  if (!form || !input || !list || !total || !clearBtn || !empty || !error) return;

  function load() {
    try {
      var v = JSON.parse(localStorage.getItem(KEY) || '[]');
      if (!Array.isArray(v)) return [];
      return v.filter(function (x) { return typeof x === 'string' && x.trim() !== ''; });
    } catch (e) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(KEY, JSON.stringify(items));
    } catch (e) {
      // Storage unavailable or full; app continues in memory.
    }
  }

  var items = load();

  function render() {
    list.textContent = '';
    items.forEach(function (text, i) {
      var li = document.createElement('li');
      li.className = 'item';

      var span = document.createElement('span');
      span.textContent = text;

      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'ghost small';
      del.textContent = 'Remove';
      del.setAttribute('aria-label', 'Remove ' + text);
      del.addEventListener('click', function () {
        items.splice(i, 1);
        save();
        render();
        input.focus();
      });

      li.appendChild(span);
      li.appendChild(del);
      list.appendChild(li);
    });
    total.textContent = String(items.length);
    empty.hidden = items.length > 0;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) {
      error.hidden = false;
      input.focus();
      return;
    }
    error.hidden = true;
    items.push(text);
    save();
    input.value = '';
    render();
    input.focus();
  });

  input.addEventListener('input', function () {
    if (input.value.trim() !== '') error.hidden = true;
  });

  clearBtn.addEventListener('click', function () {
    items = [];
    save();
    error.hidden = true;
    render();
    input.focus();
  });

  render();
})();

