(function () {
  'use strict';

  var form = document.getElementById('calc-form');
  var inputA = document.getElementById('a');
  var inputB = document.getElementById('b');
  var button = document.getElementById('calculate');
  var result = document.getElementById('result');
  var error = document.getElementById('error');

  if (!form || !inputA || !inputB || !button || !result || !error) return;

  // Number of decimal places in a numeric string, accounting for exponent notation.
  function decimalPlaces(str) {
    var m = /^[+-]?\d*(?:\.(\d+))?(?:e([+-]?\d+))?$/i.exec(str.trim());
    if (!m) return 0;
    var frac = m[1] ? m[1].length : 0;
    var exp = m[2] ? parseInt(m[2], 10) : 0;
    return Math.max(0, Math.min(100, frac - exp));
  }

  function calculate() {
    var rawA = inputA.value;
    var rawB = inputB.value;
    var a = Number(rawA);
    var b = Number(rawB);

    if (rawA.trim() === '' || rawB.trim() === '' || !isFinite(a) || !isFinite(b)) {
      result.textContent = '';
      error.textContent = 'Enter a valid number in both fields.';
      return;
    }

    error.textContent = '';
    var places = Math.max(decimalPlaces(rawA), decimalPlaces(rawB));
    var sum = Number((a + b).toFixed(places));
    result.textContent = String(sum);
  }

  form.addEventListener('submit', function (event) {
    event.preventDefault();
    calculate();
  });

  button.addEventListener('click', function (event) {
    event.preventDefault();
    calculate();
  });
})();

(function () {
  'use strict';

  var buttons = {
    overview: document.getElementById('tab-overview'),
    details: document.getElementById('tab-details')
  };
  var panel = document.getElementById('panel');
  if (!panel || !buttons.overview || !buttons.details) return;

  var content = {
    overview: {
      title: 'Overview',
      text: 'This is the overview section. Select Details to view more information.'
    },
    details: {
      title: 'Details',
      text: 'This is the details section. Select Overview to return to the summary.'
    }
  };

  function buildSection(name) {
    var data = content[name];
    var section = document.createElement('section');
    section.id = name;
    section.setAttribute('aria-labelledby', name + '-title');

    var heading = document.createElement('h2');
    heading.id = name + '-title';
    heading.textContent = data.title;

    var para = document.createElement('p');
    para.textContent = data.text;

    section.appendChild(heading);
    section.appendChild(para);
    return section;
  }

  // Single source of tab state: aria-pressed on the buttons.
  function select(name) {
    Object.keys(buttons).forEach(function (key) {
      buttons[key].setAttribute('aria-pressed', key === name ? 'true' : 'false');
    });
    // Replace the container's contents so only the active section is in the DOM.
    panel.replaceChildren(buildSection(name));
  }

  buttons.overview.addEventListener('click', function () { select('overview'); });
  buttons.details.addEventListener('click', function () { select('details'); });

  // Initial state: Overview active, Details not in the DOM.
  select('overview');
})();

