(function () {
  'use strict';

  var TABS = {
    overview: { button: 'tab-overview', template: 'tpl-overview' },
    details: { button: 'tab-details', template: 'tpl-details' }
  };
  var ORDER = ['overview', 'details'];

  function getButton(name) {
    return document.getElementById(TABS[name].button);
  }

  function showTab(name) {
    var panel = document.getElementById('panel');
    var tpl = document.getElementById(TABS[name].template);
    if (!panel || !tpl) return;

    // Replace panel contents with only the active section.
    panel.replaceChildren(tpl.content.cloneNode(true));

    ORDER.forEach(function (key) {
      var btn = getButton(key);
      if (btn) btn.setAttribute('aria-pressed', key === name ? 'true' : 'false');
    });
  }

  function currentTab() {
    for (var i = 0; i < ORDER.length; i++) {
      var btn = getButton(ORDER[i]);
      if (btn && btn.getAttribute('aria-pressed') === 'true') return ORDER[i];
    }
    return 'overview';
  }

  function init() {
    ORDER.forEach(function (name) {
      var btn = getButton(name);
      if (!btn) return;
      btn.addEventListener('click', function () {
        showTab(name);
      });
      btn.addEventListener('keydown', function (e) {
        // Arrow keys move focus between tabs (and activate them), per the tabs pattern.
        if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
        e.preventDefault();
        var idx = ORDER.indexOf(name);
        var next = ORDER[(idx + (e.key === 'ArrowRight' ? 1 : ORDER.length - 1)) % ORDER.length];
        var nextBtn = getButton(next);
        if (nextBtn) {
          nextBtn.focus();
          showTab(next);
        }
      });
    });

    showTab(currentTab());
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

