(function () {
  const KEY = 'count';
  const countEl = document.querySelector('#count');
  const addBtn = document.querySelector('#add');
  const subtractBtn = document.querySelector('#subtract');
  const resetBtn = document.querySelector('#reset');

  const stored = Number(localStorage.getItem(KEY));
  let n = Number.isFinite(stored) ? stored : 0;

  function render() {
    if (countEl) countEl.textContent = String(n);
    try {
      localStorage.setItem(KEY, String(n));
    } catch (e) {
      /* storage unavailable; counter still works in memory */
    }
  }

  if (addBtn) addBtn.onclick = () => { n++; render(); };
  if (subtractBtn) subtractBtn.onclick = () => { n--; render(); };
  if (resetBtn) resetBtn.onclick = () => { n = 0; render(); };

  render();
})();

(function () {
  const KEY = 'count';
  const countEl = document.querySelector('#count');
  const addBtn = document.querySelector('#add');
  const subtractBtn = document.querySelector('#subtract');
  const resetBtn = document.querySelector('#reset');

  function load() {
    try {
      const raw = localStorage.getItem(KEY);
      const v = Number(raw);
      return raw !== null && Number.isFinite(v) ? Math.trunc(v) : 0;
    } catch (e) {
      return 0;
    }
  }

  let n = load();

  function save() {
    try { localStorage.setItem(KEY, String(n)); } catch (e) { /* storage unavailable */ }
  }

  function render() {
    if (countEl) countEl.textContent = String(n);
    save();
  }

  if (addBtn) addBtn.addEventListener('click', () => { n++; render(); });
  if (subtractBtn) subtractBtn.addEventListener('click', () => { n--; render(); });
  if (resetBtn) resetBtn.addEventListener('click', () => { n = 0; render(); });

  render();
})();

